"""Query execution for the small CSV-backed SQL engine."""
import csv, os, re, math
from collections import OrderedDict
from decimal import Decimal, ROUND_HALF_UP

class QueryError(Exception):
    pass

NULL = None
AGGS = {'count','sum','avg','min','max'}

def _convert(s):
    if s == '': return None
    if re.fullmatch(r'-?[0-9]+', s):
        try: return int(s)
        except ValueError: pass
    if re.fullmatch(r'-?(?:[0-9]+\.[0-9]*|[0-9]*\.[0-9]+)', s):
        try: return float(s)
        except ValueError: pass
    return s

def _truth(v): return v is True

def _numeric(v): return isinstance(v, (int,float)) and not isinstance(v,bool)

def _compare(a,b,op):
    if a is None or b is None: return None
    if _numeric(a) and _numeric(b): pass
    elif type(a) is type(b) and isinstance(a,(str,bool)): pass
    else: raise QueryError('incompatible values in comparison')
    try: return {'=':lambda:a==b,'==':lambda:a==b,'!=':lambda:a!=b,'<>':lambda:a!=b,'<':lambda:a<b,'<=':lambda:a<=b,'>':lambda:a>b,'>=':lambda:a>=b}[op]()
    except (TypeError,KeyError): raise QueryError('invalid comparison')

