    name=expr.value.lower(); args=expr.args
    if name=='count' and (not args or getattr(args[0],'kind',None)=='star'): return len(rows)
    vals=[_eval(args[0],row,headers) for row in rows] if args else []
    vals=[v for v in vals if v is not None]
    if name=='count': return len(vals)
    if not vals: return None
    if name in ('sum','avg'):
        if any(not _numeric(v) for v in vals): raise QueryError(name.upper()+' requires numeric values')
        return sum(vals) if name=='sum' else float(sum(vals)/len(vals))
    for x in vals[1:]: _compare(vals[0],x,'=')
    return min(vals) if name=='min' else max(vals)

