        if fn not in arity: raise QueryError('unknown function: '+str(v))
        lo,hi=arity[fn]
        if len(vals)<lo or (hi is not None and len(vals)>hi): raise QueryError('wrong number of arguments to '+fn)
        if fn=='coalesce': return next((x for x in vals if x is not None),None)
        if any(x is None for x in vals): return None
        x=vals[0]
