    cols=list(query.columns)
    if len(cols)==1 and cols[0].expr.kind=='star':
        if grouped: raise QueryError('* is not valid in grouped query')
        cols=[]
        for h in raw:
            from types import SimpleNamespace
            cols.append(SimpleNamespace(expr=SimpleNamespace(kind='name',value=h,args=(),text=h),alias=None))
