                except TypeError: raise QueryError('unhashable group value')
            groups=list(lookup.values())
        else: groups=[rows]
        # Every nonaggregate name must appear as a group expression.
        if query.group_by:
            allowed={e.text for e in query.group_by}
            def check(e,inside=False):
                if e.kind=='call' and str(e.value).lower() in AGGS:return
                if e.kind=='name' and e.text not in allowed: raise QueryError('column must appear in GROUP BY')
                for x in e.args: check(x)
            for x in cols: check(x.expr)
            if query.having: check(query.having)
